//! Nepali (Bikram Sambat) calendar. BS month lengths follow no formula, so
//! conversion walks a lookup table (`months.rs`, generated by `scripts/gen_months.py`).
//! Both tables are read-only data in the binary: the OS pages them in from disk
//! on demand, so they cost no heap.

mod months;
use months::{EPOCH, FIRST_YEAR, MONTHS};
use std::{fmt, str::FromStr, time::SystemTime};

/// Per-day tithi/holiday/event rows: `bs-date \t tithi \t H|- \t event_np \t event_en`.
const DAYS: &str = include_str!("../data/days.tsv");

pub const MONTHS_NP: [&str; 12] = [
    "बैशाख", "जेठ", "असार", "साउन", "भदौ", "असोज", "कार्तिक", "मंसिर", "पुष", "माघ", "फागुन", "चैत",
];
pub const MONTHS_EN: [&str; 12] = [
    "Baisakh", "Jestha", "Asar", "Shrawan", "Bhadra", "Ashwin", "Kartik", "Mangsir", "Poush",
    "Magh", "Falgun", "Chaitra",
];
/// Index 0 is Sunday.
pub const WEEKDAYS_NP: [&str; 7] =
    ["आइतवार", "सोमवार", "मंगलवार", "बुधवार", "बिहीवार", "शुक्रवार", "शनिवार"];
pub const WEEKDAYS_EN: [&str; 7] =
    ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

/// A Bikram Sambat date. `month` and `day` are 1-based.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct Bs {
    pub year: u16,
    pub month: u8,
    pub day: u8,
}

/// Tithi, holiday and events for a day. Only available for a few years around now.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DayInfo {
    pub tithi: &'static str,
    pub holiday: bool,
    pub event_np: &'static str,
    pub event_en: &'static str,
}

/// Days in a BS month, or `None` outside the table.
pub fn days_in_month(year: u16, month: u8) -> Option<u8> {
    let y = MONTHS.get(year.checked_sub(FIRST_YEAR)? as usize)?;
    y.get(month.checked_sub(1)? as usize).copied()
}

impl Bs {
    /// From days since 1970-01-01 AD. `None` outside the table.
    pub fn from_unix_days(days: i32) -> Option<Bs> {
        let mut left = days.checked_sub(EPOCH).filter(|d| *d >= 0)?;
        for (y, months) in MONTHS.iter().enumerate() {
            for (m, &len) in months.iter().enumerate() {
                if left < len as i32 {
                    return Some(Bs { year: FIRST_YEAR + y as u16, month: m as u8 + 1, day: left as u8 + 1 });
                }
                left -= len as i32;
            }
        }
        None
    }

    /// Days since 1970-01-01 AD. `None` if the date is invalid or outside the table.
    pub fn to_unix_days(self) -> Option<i32> {
        if self.day == 0 || self.day > days_in_month(self.year, self.month)? {
            return None;
        }
        let y = (self.year - FIRST_YEAR) as usize;
        let before = MONTHS[..y].iter().flatten().chain(&MONTHS[y][..self.month as usize - 1]);
        Some(EPOCH + before.map(|&d| d as i32).sum::<i32>() + self.day as i32 - 1)
    }

    /// From a Gregorian date. `None` if that date is invalid or outside the table.
    pub fn from_ad(year: i32, month: u8, day: u8) -> Option<Bs> {
        let days = days_from_civil(year, month, day);
        (civil_from_days(days) == (year, month, day)).then(|| Bs::from_unix_days(days))?
    }

    /// Gregorian `(year, month, day)`.
    pub fn to_ad(self) -> Option<(i32, u8, u8)> {
        self.to_unix_days().map(civil_from_days)
    }

    /// Today in Nepal (UTC+5:45), whatever the system timezone is.
    pub fn today() -> Option<Bs> {
        let secs = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).ok()?.as_secs();
        Bs::from_unix_days(((secs + 5 * 3600 + 45 * 60) / 86400) as i32)
    }

    /// 0 = Sunday.
    pub fn weekday(self) -> Option<u8> {
        // 1970-01-01 was a Thursday.
        self.to_unix_days().map(|d| (d + 4).rem_euclid(7) as u8)
    }

    /// Tithi, holiday and event for this day, if there is data for it.
    pub fn info(self) -> Option<DayInfo> {
        let key = format!("{self}\t");
        let mut f = DAYS.lines().find(|l| l.starts_with(&key))?.split('\t').skip(1);
        Some(DayInfo {
            tithi: f.next()?,
            holiday: f.next()? == "H",
            event_np: f.next()?,
            event_en: f.next()?,
        })
    }
}

/// `YYYY-MM-DD`.
impl fmt::Display for Bs {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{:04}-{:02}-{:02}", self.year, self.month, self.day)
    }
}

/// Parses `YYYY-MM-DD` and checks the day exists.
impl FromStr for Bs {
    type Err = String;
    fn from_str(s: &str) -> Result<Bs, String> {
        let mut p = s.split('-');
        let mut num = || p.next()?.parse::<u16>().ok();
        let bs = (|| Some(Bs { year: num()?, month: num()? as u8, day: num()? as u8 }))()
            .ok_or_else(|| format!("bad date '{s}', want YYYY-MM-DD"))?;
        bs.to_unix_days().map(|_| bs).ok_or_else(|| format!("no such BS date in table: {s}"))
    }
}

/// Number in Devanagari digits.
pub fn np_digits(n: u32) -> String {
    n.to_string().bytes().map(|b| char::from_u32(0x0966 + (b - b'0') as u32).unwrap()).collect()
}

/// `YYYY-MM-DD` Gregorian date of `bs`.
pub fn ad_str(bs: Bs) -> String {
    let (y, m, d) = bs.to_ad().unwrap(); // every constructed Bs is in the table
    format!("{y:04}-{m:02}-{d:02}")
}

/// One day as the JSON object every widget and the GUI decode.
pub fn day_json(bs: Bs) -> String {
    let (m, w) = (bs.month as usize - 1, bs.weekday().unwrap() as usize);
    let i = bs.info();
    let (tithi, ev_np, ev_en) = i.map_or(("", "", ""), |i| (i.tithi, i.event_np, i.event_en));
    let esc = |s: &str| s.replace('\\', "\\\\").replace('"', "\\\"");
    format!(
        "{{\"bs\":\"{bs}\",\"ad\":\"{}\",\"year\":{},\"month\":{},\"day\":{},\"weekday\":{w},\
         \"year_np\":\"{}\",\"month_np\":\"{}\",\"day_np\":\"{}\",\"weekday_np\":\"{}\",\
         \"month_en\":\"{}\",\"weekday_en\":\"{}\",\"tithi\":\"{}\",\"holiday\":{},\
         \"event_np\":\"{}\",\"event_en\":\"{}\"}}",
        ad_str(bs),
        bs.year,
        bs.month,
        bs.day,
        np_digits(bs.year as u32),
        MONTHS_NP[m],
        np_digits(bs.day as u32),
        WEEKDAYS_NP[w],
        MONTHS_EN[m],
        WEEKDAYS_EN[w],
        esc(tithi),
        i.is_some_and(|i| i.holiday),
        esc(ev_np),
        esc(ev_en),
    )
}

/// A whole BS month as JSON (`days` holds one `day_json` object each); `None` outside the table.
pub fn month_json(year: u16, month: u8) -> Option<String> {
    let days: Vec<String> =
        (1..=days_in_month(year, month)?).map(|day| day_json(Bs { year, month, day })).collect();
    let m = month as usize - 1;
    Some(format!(
        "{{\"year\":{year},\"month\":{month},\"year_np\":\"{}\",\"month_np\":\"{}\",\"month_en\":\"{}\",\"days\":[{}]}}",
        np_digits(year as u32),
        MONTHS_NP[m],
        MONTHS_EN[m],
        days.join(","),
    ))
}

// Proleptic Gregorian <-> day count, after Howard Hinnant's `days_from_civil`.
fn days_from_civil(y: i32, m: u8, d: u8) -> i32 {
    let y = if m <= 2 { y - 1 } else { y };
    let (era, yoe) = (y.div_euclid(400), y.rem_euclid(400));
    let doy = (153 * ((m as i32 + 9) % 12) + 2) / 5 + d as i32 - 1;
    era * 146097 + yoe * 365 + yoe / 4 - yoe / 100 + doy - 719468
}

fn civil_from_days(z: i32) -> (i32, u8, u8) {
    let z = z + 719468;
    let (era, doe) = (z.div_euclid(146097), z.rem_euclid(146097));
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (yoe + era * 400 + (m <= 2) as i32, m as u8, (doy - (153 * mp + 2) / 5 + 1) as u8)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_dates() {
        // 1901-01-01 is the table's epoch and 2199-12-30 its last day; the others are spot checks.
        for (bs, ad) in [
            ("1901-01-01", (1844, 4, 11)),
            ("1975-01-01", (1918, 4, 13)),
            ("2000-01-01", (1943, 4, 14)),
            ("2081-01-01", (2024, 4, 13)),
            ("2083-07-27", (2026, 11, 13)),
            ("2199-12-30", (2143, 4, 15)),
        ] {
            let bs: Bs = bs.parse().unwrap();
            assert_eq!(bs.to_ad(), Some(ad));
            assert_eq!(Bs::from_ad(ad.0, ad.1, ad.2), Some(bs));
        }
        assert_eq!("2083-07-27".parse::<Bs>().unwrap().weekday(), Some(5)); // Friday
    }

    #[test]
    fn every_day_round_trips() {
        let total: i32 = MONTHS.iter().flatten().map(|&d| d as i32).sum();
        for days in EPOCH..EPOCH + total {
            let bs = Bs::from_unix_days(days).unwrap();
            assert_eq!(bs.to_unix_days(), Some(days));
            let (y, m, d) = civil_from_days(days);
            assert_eq!(Bs::from_ad(y, m, d), Some(bs));
        }
        assert_eq!(Bs::from_unix_days(EPOCH - 1), None);
        assert_eq!(Bs::from_unix_days(EPOCH + total), None);
    }

    #[test]
    fn rejects_bad_input() {
        assert_eq!(Bs::from_ad(2026, 2, 30), None);
        assert_eq!(Bs::from_ad(2026, 13, 1), None);
        assert!("2083-08-30".parse::<Bs>().is_err()); // Mangsir 2083 has 29 days
        assert!("2083-00-01".parse::<Bs>().is_err());
        assert!("garbage".parse::<Bs>().is_err());
    }

    #[test]
    fn day_info() {
        let i = "2083-08-19".parse::<Bs>().unwrap().info().unwrap();
        assert_eq!(i.tithi, "द्वादशी");
        assert!(i.event_en.contains("World Soil Day"));
        assert_eq!(np_digits(2083), "२०८३");
    }
}
